example.code:
#[DataProvider('totalCases')]
public function test_calculates_total(array $items, int $expectedCents): void
{
    // Arrange
    $discounts = $this->createMock(DiscountService::class);
    $discounts->method('for')->willReturn(Money::zero());
    $service = new OrderService($discounts);

    // Act
    $total = $service->calculateTotal($items);

    // Assert
    $this->assertSame($expectedCents, $total->cents());
}

public static function totalCases(): array
{
    return [
        'empty basket'  => [[], 0],
        'single line'   => [[['cents' => 1200, 'qty' => 1]], 1200],
        'two lines'     => [[['cents' => 1200, 'qty' => 2]], 2400],
    ];
}
